import{_ as u,a8 as l,o as g,c as d,ah as q,a as o,a3 as e,K as n,L as r}from"./chunks/framework.DX2Vcg1x.js";import"./chunks/theme.BzIrHAwa.js";const _=JSON.parse('{"title":"网页笔记四步工作流","description":"","frontmatter":{"title":"网页笔记四步工作流","created":"2026-07-14T00:00:00.000Z","type":"概念解释","tags":["ai","knowledge-management","pkm","web-clipping","workflow","Agent","多Agent","工作流","知识管理","笔记"]},"headers":[],"relativePath":"vault/作坊/网页笔记四步工作流.md","filePath":"vault/Workshop/网页笔记四步工作流.md","lastUpdated":1793173648000}'),A={name:"vault/作坊/网页笔记四步工作流.md"};function p(h,t,b,f,k,m){const a=l("VPNolebaseInlineLinkPreview"),s=l("NolebaseGitContributors"),i=l("NolebaseGitChangelog");return g(),d("div",null,[t[10]||(t[10]=q('<h1 id="别让-ai-自己查自己-一条-可信优先-的网页笔记四步工作流" tabindex="-1">别让 AI 自己查自己：一条&quot;可信优先&quot;的网页笔记四步工作流 <a class="header-anchor" href="#别让-ai-自己查自己-一条-可信优先-的网页笔记四步工作流" aria-label="Permalink to “别让 AI 自己查自己：一条&quot;可信优先&quot;的网页笔记四步工作流”">​</a></h1><blockquote><p>摘要：把网页内容交给 AI 提炼笔记很方便，但它会一脸自信地编造事实，而你往往看不出来。本文介绍一个开源的「网页笔记四步工作流」——把整理、提炼、独立核查、人工确认拆成四个各管一段的 Agent。它的核心不是&quot;更自动&quot;，而是&quot;可控的自动化&quot;：AI 可以无限地建议，但凡要落地动手，都停在你这道闸前。本项目是在 Axton Liu《Agent OS 的第一课：会分工，才会用 Agent》一文的理念启发下，自行实现与改进的一套可复用工作流。</p></blockquote><hr><h2 id="一、问题-ai-做笔记-编得比你想象的多" tabindex="-1">一、问题：AI 做笔记，编得比你想象的多 <a class="header-anchor" href="#一、问题-ai-做笔记-编得比你想象的多" aria-label="Permalink to “一、问题：AI 做笔记，编得比你想象的多”">​</a></h2><p>让同一个 AI 一口气&quot;读网页 → 提要点 → 写进知识库&quot;，有一个结构性风险：<strong>它在提炼时会把&quot;听起来对&quot;的当成&quot;对的&quot;写出来</strong>，而且不是故意骗你——它只是自信地脑补。更麻烦的是，如果你再让<strong>同一个</strong> AI 去核查它刚写的笔记，它查不出来：盲区一样，它只会顺着自己的逻辑往下圆，等于让一个人审自己的卷子。</p><p>于是真正的瓶颈就浮现了：AI 做笔记，卡点从来不是&quot;能不能提炼&quot;，而是&quot;提炼出来的东西你敢不敢信&quot;。要解决它，靠的不是换个更聪明的模型，而是给流程加上&quot;防自己&quot;的结构。</p><h2 id="二、思路-把-可信-拆进流程的三道闸" tabindex="-1">二、思路：把&quot;可信&quot;拆进流程的三道闸 <a class="header-anchor" href="#二、思路-把-可信-拆进流程的三道闸" aria-label="Permalink to “二、思路：把&quot;可信&quot;拆进流程的三道闸”">​</a></h2><p>这套工作流只盯着一个目标——<strong>让 AI 编的东西尽可能在落地前被拦下来</strong>。为此设计了三道闸：</p><p><strong>第一道闸：分工隔离。</strong> 把&quot;整理 → 提炼 → 核查 → 确认&quot;拆成四个独立 Agent，每个拥有干净、互不可见的上下文。提炼的只管从正文提要点，不碰核查；核查的只拿&quot;原文 + 笔记成品&quot;逐条比对，不掺和提炼时的思路。上下文一隔离，Agent&quot;想包庇自己都做不到&quot;。</p><p><strong>第二道闸：独立核查。</strong> 这是整套里最容易被跳过、也最关键的一道。核查 Agent 必须是一份没参与过提炼的&quot;白纸&quot;，只做一件事：把笔记里每条要点、每个数字、每个结论回到原文逐条比对，对不上或原文根本没有的，标&quot;可疑 / 原文无依据&quot;。省掉这一步，假信息迟早进知识库。</p><p><strong>第三道闸：确认闸。</strong> 前面三道再能干，也只是把活干完、把建议摆好。所有删除、归档、发布、写入长期记忆的动作，都停在&quot;待确认&quot;，由你逐条点头才落地。</p><p>一句话概括这套哲学：<strong>AI 可以无限地&quot;想&quot;和&quot;建议&quot;，但凡要&quot;落地动手&quot;，停在你这道闸前。</strong></p><h2 id="三、四个-agent-各管一段" tabindex="-1">三、四个 Agent 各管一段 <a class="header-anchor" href="#三、四个-agent-各管一段" aria-label="Permalink to “三、四个 Agent 各管一段”">​</a></h2><ul><li><strong>Agent 1 · 整理</strong>：把你<strong>已经存好</strong>的网页（标题 + 网址 + 正文）登记成一张清单，做初步四选一分类——学习（能上手的方法）、借鉴（写法结构）、内容补充（补事实数据）、可归档（信号低或重复）。它不提炼、不下结论，只负责&quot;读进来、归类&quot;。没有正文的，如实标&quot;无&quot;，绝不拿标题硬凑。</li><li><strong>Agent 2 · 提炼</strong>：从有正文的页面里提取 3–5 条核心要点，每条标注在正文里的位置（第几段、哪句话附近），再给一句&quot;为什么值得保留&quot;和修订建议。铁律是只依据正文，正文里没有的数字、结论一律不写。</li><li><strong>Agent 3 · 核查</strong>：拿提炼的笔记，逐条回到原文比对。对得上的标&quot;已核实&quot;并给出处，对不上的标&quot;可疑&quot;并说清冲突在哪。它是全新的 Agent，和提炼的不是同一个，所以不会替它辩护。</li><li><strong>Agent 4 · 确认</strong>：把前三道产出汇总成一份&quot;待确认提案&quot;，每条给建议动作（保留 / 修正 / 删除）和理由，被标&quot;可疑&quot;的条目单独列出。全部停在待确认，不自动执行任何动作。</li></ul><h2 id="四、一个前提-正文由你存好-本项目不抓网页" tabindex="-1">四、一个前提：正文由你存好，本项目不抓网页 <a class="header-anchor" href="#四、一个前提-正文由你存好-本项目不抓网页" aria-label="Permalink to “四、一个前提：正文由你存好，本项目不抓网页”">​</a></h2><p>需要特别说明的是：<strong>这套工作流只处理&quot;已经存好的内容&quot;，它本身不去抓网页。</strong> 直接让 AI 现抓，十有八九抓不全，付费墙和需登录的页更抓不到。所以正文这道又脏又不稳的活，交给你顺手的工具——Obsidian 网页剪藏、简悦、Cubox、Readwise Reader，甚至手动复制粘贴都行；如果愿意，也可以用能操作已登录浏览器的桥接工具（例如腾讯开源的 BrowserSkill）。<strong>用哪种、用不用，完全由你决定</strong>，工作流不做强制。</p><p>正文存好后，四个 Agent 才上场。它们只干 AI 真正擅长的归类和判断，不碰它不擅长的抓取。而且原文<strong>只被引用、不被复制、不被修改</strong>：每次运行只在索引里记录原文的所在路径，核查时按路径回到原文比对。</p><h2 id="五、三种用法-从零门槛到全自动" tabindex="-1">五、三种用法，从零门槛到全自动 <a class="header-anchor" href="#五、三种用法-从零门槛到全自动" aria-label="Permalink to “五、三种用法，从零门槛到全自动”">​</a></h2><p>这套流程不挑工具，按你手头的 AI 选一种：</p><ol><li><strong>多 Agent 版（推荐）</strong>：工具支持 subagent（如 WorkBuddy、Claude Code、Codex）时，把调度器提示词连同工作流文档一起交给它，它会自动创建四个独立 Agent 接力跑完。</li><li><strong>单对话框版（零门槛）</strong>：只有普通对话框也行，关键是&quot;分段交付&quot;——第一段做整理+提炼后停下；第二段<strong>必须新开一个对话</strong>贴入核查提示词 + 原文 + 笔记跑核查；第三段再回来做确认。核查换新对话这一步不能省，否则又变成自己查自己。</li><li><strong>文件流水线</strong>：把四个 Agent 串成文件流水线，每次运行在 <code>runs/</code> 下建一个 <code>YYYY-MM-DD-主题</code> 子目录，四个输出文件并列写入，多次运行互不覆盖，原文只读不改。</li></ol><h2 id="六、为什么每一步都落盘成文件" tabindex="-1">六、为什么每一步都落盘成文件 <a class="header-anchor" href="#六、为什么每一步都落盘成文件" aria-label="Permalink to “六、为什么每一步都落盘成文件”">​</a></h2><p>这套流程的每一步产出都是一份独立的 Markdown：整理清单、提炼笔记、核查表、待确认提案。这么做有三个好处：<strong>可检查</strong>（你能自己翻核查表，看 AI 到底哪条被判可疑）、<strong>可恢复</strong>（中断了从任一步接着跑）、<strong>可替换</strong>（今天用 Claude、明天用 Codex，流程照样在）。透明、可溯源、可逆——这比盲信一个&quot;全能助手&quot;踏实得多。</p><h2 id="七、谁适合用这套工作流" tabindex="-1">七、谁适合用这套工作流 <a class="header-anchor" href="#七、谁适合用这套工作流" aria-label="Permalink to “七、谁适合用这套工作流”">​</a></h2><ul><li>收藏了大量网页 / 文章，但&quot;存了等于读了&quot;的收藏夹吃灰党；</li><li>把 AI 当研究助手，又不想被它一本正经地误导；</li><li>在做知识管理、写周报、建选题库，需要可溯源素材的人；</li><li>认同&quot;自动化要可控&quot;，愿意为可靠性多花那一步确认成本的人。</li></ul><p>如果你只是偶尔让 AI 总结一篇文章，那没必要上这套。但只要你开始把 AI 的产出当&quot;知识&quot;长期积累，独立核查和确认闸就不是可选项，而是必选项。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h2><p>这套「网页笔记四步工作流」没有让 AI 变得更聪明，而是用分工隔离上下文、用独立核查拦住编造、用确认闸把最终决定权留在你手里，让 AI 的产出变得<strong>可信</strong>。它的理念源自 Axton Liu《Agent OS 的第一课：会分工，才会用 Agent》——分工隔离、独立核查、确认闸门三层设计；本项目在此基础上，落地成一套可直接复用、按文件流水线运行的开源实现。</p><hr>',28)),o("p",null,[o("em",null,[t[1]||(t[1]=e("设计参考：",-1)),n(a,{href:"https://www.axtonliu.ai/newsletters/ai-2/posts/agent-os-workstation-division",target:"_blank",rel:"noreferrer"},{default:r(()=>[...t[0]||(t[0]=[e("Agent OS 的第一课：会分工，才会用 Agent",-1)])]),_:1}),t[2]||(t[2]=e("（Axton Liu）。",-1))])]),o("p",null,[o("em",null,[t[4]||(t[4]=e("项目已开源：",-1)),n(a,{href:"https://github.com/star-nebula/WebNote-Workflow",target:"_blank",rel:"noreferrer"},{default:r(()=>[...t[3]||(t[3]=[e("github.com/star-nebula/WebNote-Workflow",-1)])]),_:1}),t[5]||(t[5]=e("。仓库含完整目录结构、三种用法与确认边界说明，欢迎 Star / Fork。",-1))])]),t[11]||(t[11]=o("h2",{id:"相关阅读",tabindex:"-1"},[e("相关阅读 "),o("a",{class:"header-anchor",href:"#相关阅读","aria-label":"Permalink to “相关阅读”"},"​")],-1)),o("ul",null,[o("li",null,[n(a,{href:"/knowledge/vault/Knowledge/AI/RAG 核心知识点全集.html"},{default:r(()=>[...t[6]||(t[6]=[e("RAG 检索增强生成",-1)])]),_:1})]),o("li",null,[n(a,{href:"/knowledge/vault/Knowledge/AI/n8n AI Agent 工作流.html"},{default:r(()=>[...t[7]||(t[7]=[e("n8n AI Agent 工作流",-1)])]),_:1})]),o("li",null,[n(a,{href:"/knowledge/vault/Knowledge/AI/LangChain Agents 组件.html"},{default:r(()=>[...t[8]||(t[8]=[e("LangChain Agents 组件",-1)])]),_:1})]),o("li",null,[n(a,{class:"route-link nolebase-route-link-invalid",href:"#",target:"_target"},{default:r(()=>[...t[9]||(t[9]=[e("Knowledge/AI/大模型-基础",-1)])]),_:1})])]),n(s),n(i)])}const x=u(A,[["render",p]]);export{_ as __pageData,x as default};
